// Zad X brand refresh (owner decision 2026-11-27):
// * the "ZX" artwork is the phone/desktop icon of both apps (Zad X Play and Zad X Kids);
// * "ZX ZAD X" is the logo inside Zad X Play, "ZX" alone on the splash;
// * the splash and the parent area of Zad X Play use the brand navy backdrop.
// Images are generated by tools/gen_brand_assets.py from tools/branding/source/.
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zadx/core/app_variant.dart';
import 'package:zadx/core/theme/app_colors.dart';
import 'package:zadx/shared/art/scenes/brand_backdrop.dart';
import 'package:zadx/shared/art/zad_art.dart';
import 'package:zadx/shared/widgets/brand_logo.dart';

const _densities = ['mdpi', 'hdpi', 'xhdpi', 'xxhdpi', 'xxxhdpi'];
const _res = 'android/app/src/main/res';

void main() {
  group('launcher icons (both apps)', () {
    test('Android: legacy + adaptive icon in every density', () {
      for (final d in _densities) {
        for (final name in ['ic_launcher', 'ic_launcher_foreground', 'ic_launcher_background']) {
          expect(File('$_res/mipmap-$d/$name.png').existsSync(), isTrue, reason: '$d/$name');
        }
      }
      final xml = File('$_res/mipmap-anydpi-v26/ic_launcher.xml').readAsStringSync();
      expect(xml, contains('<adaptive-icon'));
      expect(xml, contains('@mipmap/ic_launcher_foreground'));
      expect(xml, contains('@mipmap/ic_launcher_background'));
    });

    test('iOS: every icon listed in Contents.json exists, including the 1024 store icon', () {
      const dir = 'ios/Runner/Assets.xcassets/AppIcon.appiconset';
      final contents = jsonDecode(File('$dir/Contents.json').readAsStringSync()) as Map<String, dynamic>;
      final images = (contents['images'] as List).cast<Map<String, dynamic>>();
      expect(images.any((i) => i['idiom'] == 'ios-marketing' && i['size'] == '1024x1024'), isTrue);
      for (final i in images) {
        expect(File('$dir/${i['filename']}').existsSync(), isTrue, reason: '${i['filename']}');
      }
    });

    test('store icon and web icons are in place', () {
      expect(File('docs/store/assets/play-icon-512.png').existsSync(), isTrue);
      for (final f in ['web/favicon.png', 'web/icons/Icon-192.png', 'web/icons/Icon-512.png',
        'web/icons/Icon-maskable-192.png', 'web/icons/Icon-maskable-512.png']) {
        expect(File(f).existsSync(), isTrue, reason: f);
      }
    });
  });

  if (!kIsKids) {
    group('Zad X Play logo', () {
      test('logo images are bundled and the old artwork logo is gone', () {
        expect(File(BrandLogo.wordmarkAsset).existsSync(), isTrue);
        expect(File(BrandLogo.emblemAsset).existsSync(), isTrue);
        expect(File('assets/images/zadx_logo.jpg').existsSync(), isFalse);
        expect(File('pubspec.yaml').readAsStringSync(), contains('- assets/images/'));
      });

      testWidgets('wordmark by default, "ZX" emblem on request', (tester) async {
        await tester.pumpWidget(const Directionality(
          textDirection: TextDirection.ltr,
          child: Column(children: [BrandLogo(), BrandLogo(emblem: true, width: 120, height: 120)]),
        ));
        final images = tester.widgetList<Image>(find.byType(Image)).map((i) => (i.image as AssetImage).assetName).toList();
        expect(images, [BrandLogo.wordmarkAsset, BrandLogo.emblemAsset]);
      });
    });

    test('parent area uses the brand navy with light text', () {
      expect(ZadScene.parent.palette.dark, isTrue);
      expect(ZadScene.parent.titleColor, AppColors.onNavy);
      expect(ZadScene.parent.bodyColor, AppColors.onNavyMuted);
    });
  } else {
    test('Zad X Kids keeps its light parent area', () {
      expect(ZadScene.parent.palette.dark, isFalse);
      expect(ZadScene.parent.titleColor, AppColors.ink);
    });
  }

  test('child scenes stay light (owner decision 2026-11-27: navy for splash + parent area only)', () {
    for (final s in [ZadScene.home, ZadScene.games, ZadScene.tasks]) {
      expect(s.palette.dark, isFalse, reason: s.name);
    }
  });

  testWidgets('brand backdrop paints, with and without the splash ring', (tester) async {
    for (final ring in [false, true]) {
      await tester.pumpWidget(CustomPaint(painter: BrandBackdropPainter(ring: ring), size: const Size(360, 640)));
      expect(tester.takeException(), isNull);
    }
  });
}
